"""Private exact-protocol recovery on durable Kaggle notebook outputs.
This job closes the original 1,935,360-pair matrix for one contract only.
Longevity and focal results are separate jobs and never implied complete here.
No holdout, P&L, promotion, scientific retuning or source certification.
"""
import os,sys,json,pathlib,hashlib,gzip,base64,subprocess,datetime,traceback
os.environ.update(OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1',NUMBA_NUM_THREADS='1',PYTHONUNBUFFERED='1')
C='MNQ_12-25'
EXACT_DOWNLOAD_URLS={} # Inject short-lived exact-source URLs only in private Kaggle notebook; never commit them.
WORK=pathlib.Path('/kaggle/working');assert WORK.is_dir()
DATA=WORK/'data';DATA.mkdir(exist_ok=False)
D=pathlib.Path('/data');assert not D.exists(),'UNEXPECTED_DATA_ROOT_REQUIRES_REVIEW';D.symlink_to(DATA,target_is_directory=True)
P=D/'recovery';P.mkdir()
state=dict(status='STARTING_KAGGLE_RECOVERY',contract=C,started_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),code_commit='9125197dc6098100459f36a3d90a5c7b7aa4f9c0',matrix_pairs_pending=1935360,holdout_opened=False,pnl_computed=False,source_certified=False,completed_stages=[])
def save():
 q=P/'status.tmp';q.write_text(json.dumps(state,indent=2)+'\n');os.replace(q,P/'campaign-status.json')
def sha(p):
 with pathlib.Path(p).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def run(script,stage):
 state.update(stage=stage);save();print('STAGE_START',C,stage,flush=True)
 with (P/(stage+'.log')).open('w') as log:
  subprocess.run([PY,str(script)],env={**os.environ,'REPLICATION_ROOT':str(L/C),'REPLICATION_CONTRACT':C,'FOCUS_CONTRACT':C,'MATRIX_CONTRACT':C},stdout=log,stderr=subprocess.STDOUT,check=True)
 state['completed_stages'].append(stage);save();print('STAGE_COMPLETE',C,stage,flush=True)
save()
try:
 raw=gzip.decompress(base64.b64decode(''));assert hashlib.sha256(raw).hexdigest()=='08c1dd47984c79d1d4ca110b2134189da25ccc26d3030ad0d4c3bd0c874bb742'
 b=json.loads(raw)
 for dest,enc in b['files'].items():
  p=pathlib.Path(dest);assert p.is_absolute() and str(p).startswith('/data/') and '..' not in p.parts
  p.parent.mkdir(parents=True,exist_ok=True)
  with p.open('xb') as f:f.write(base64.b64decode(enc))
 for pin in b['lineage']:assert sha(pin['destination'])==pin['sha256']
 (P/'code-provenance.json').write_text(json.dumps(dict(bundle_sha256='08c1dd47984c79d1d4ca110b2134189da25ccc26d3030ad0d4c3bd0c874bb742',lineage=b['lineage']),indent=2)+'\n')
 R=D/'raw'/'avzvol-ticks';R.mkdir();auth=json.load(open(D/'raw'/'avzvol-selected-risk'/'pr111-authorization.json'));mounts=[]
 for pin in auth['files']:
  ds=pin.get('dataset',pin.get('dataset_ref',''))
  candidates=[p for p in pathlib.Path('/kaggle/input').rglob(pin['file']) if p.stat().st_size==pin['bytes']]
  matches=[p for p in candidates if sha(p)==pin['sha256']]
  if not matches:
   import urllib.request
   scratch=pathlib.Path('/tmp/mnq-exact-sources');scratch.mkdir(exist_ok=True);local=scratch/pin['file'];part=local.with_suffix('.partial');h=hashlib.sha256();n=0
   with urllib.request.urlopen(EXACT_DOWNLOAD_URLS[pin['file']],timeout=180) as response,part.open('xb') as out:
    assert int(response.headers['Content-Length'])==pin['bytes'],'DOWNLOAD_SIZE_HEADER_MISMATCH'
    while True:
     chunk=response.read(1<<20)
     if not chunk:break
     n+=len(chunk);assert n<=pin['bytes'];h.update(chunk);out.write(chunk)
    out.flush();os.fsync(out.fileno())
   assert n==pin['bytes'] and h.hexdigest()==pin['sha256'],'EXACT_DOWNLOAD_PIN_MISMATCH'
   part.rename(local);matches=[local];print('EXACT_SOURCE_RECOVERED',pin['contract'],n,flush=True)
  assert matches,('EXACT_SOURCE_NOT_MOUNTED',pin['contract'])
  target=R/pin['file'];target.symlink_to(matches[0]);mounts.append(dict(contract=pin['contract'],dataset_version=pin['version'],bytes=pin['bytes'],sha256=pin['sha256'],input_path=str(matches[0])))
 (P/'exact-input-mounts.json').write_text(json.dumps(mounts,indent=2)+'\n');print('EXACT_SOURCES_MOUNTED',len(mounts),flush=True)
 runtime=pathlib.Path('/tmp/mnq-research-runtime');subprocess.run([sys.executable,'-m','venv','--without-pip','--system-site-packages',str(runtime)],check=True);PY=str(runtime/'bin'/'python')
 with (P/'runtime-install.log').open('w') as log:subprocess.run([sys.executable,'-m','pip','--python',PY,'install','numpy==2.3.5','pandas==3.0.6','pyarrow==26.0.0','numba==0.63.1'],stdout=log,stderr=subprocess.STDOUT,check=True)
 (P/'runtime-freeze.txt').write_text(subprocess.check_output([sys.executable,'-m','pip','--python',PY,'freeze'],text=True));(D/'analysis'/'research-runtime').symlink_to(runtime,target_is_directory=True)
 L=D/'analysis'/'avzvol-longevity';F=D/'analysis'/'avzvol-focus';(L/C).mkdir()
 run(F/'register.py','focal-registration')
 for name in ['test_engine','test_cache','test_schema','test_matrix','test_matrix_batch']:run(L/(name+'.py'),name)
 run(F/'test_gates.py','test_gates');run(P/'preflight.py','source-preflight')
 assert json.load(open(P/'preflight.json'))['status']=='PASS_EXACT_RECOVERY_PREFLIGHT'
 helper=P/'prepare-matrix-cache.py';helper.write_text("import os,sys,json,csv,pathlib,gc\nsys.path[:0]=['/data/analysis/avzvol-replication-rest','/data/analysis/avzvol-pilot','/data/analysis/avzvol-expansion']\nfrom run_replication import prepare\nC=os.environ['REPLICATION_CONTRACT'];auth=json.load(open('/data/raw/avzvol-selected-risk/pr111-authorization.json'));pin=next(x for x in auth['files'] if x['contract']==C);selected=list(csv.DictReader(open('/data/analysis/avzvol-selected-risk/selected-event-sessions.csv')));sel=[x for x in selected if x['contract']==C];metadata=json.load(open('/data/raw/avzvol-selected-risk/metadata-review.json'));win=next(x for x in metadata['contracts'] if x['contract']==C)\nresult=prepare(C,pin,sel,win);root=result[0];del result;gc.collect()\n# Only CSR buffers that the matrix reconstructs identically are discarded here.\nfor name in ['footprint-ticks-private.bin','footprint-volume-private.bin']:(root/name).unlink()\nprint('EXACT_MARKET_CACHE_PREPARED',C,flush=True)\n")
 run(helper,'market-cache-prepare')
 M=D/'analysis'/'avzvol-matrix-run'
 run(M/'run.py','full-matrix');run(M/'verify.py','matrix-coverage')
 assert json.load(open(M/C/'coverage-verification.json'))['config_rule_pairs']==1935360
 run(M/'analyze_support.py','matrix-support')
 pin=next(x for x in auth['files'] if x['contract']==C);assert sha(R/pin['file'])==pin['sha256']
 state.update(status='MATRIX_1935360_PAIRS_COMPLETE_NOT_VALIDATED_EDGE',stage='complete',matrix_pairs_pending=0,matrix_pairs_complete=1935360,source_unchanged=True);save()

except Exception as e:
 state.update(status='STOPPED_FAIL_CLOSED',error=str(e));save();traceback.print_exc();raise
finally:
 entries=[]
 for p in DATA.rglob('*'):
  if p.is_file() and not p.is_symlink() and p.suffix in ['.json','.csv','.gz','.sqlite','.npz','.bin'] and p.name!='artifact-inventory.json':
   entries.append(dict(path=str(p.relative_to(DATA)),bytes=p.stat().st_size,sha256=sha(p),private_artifact='private' in p.name))
 (P/'artifact-inventory.json').write_text(json.dumps(dict(status=state['status'],contract=C,artifacts=entries,raw_inputs_not_copied=True,matrix_pending=state.get('matrix_pairs_pending',1935360)>0),indent=2)+'\n')
 print('FINAL_STATUS',json.dumps(state),flush=True)
